using System;
using System.Linq;
using System.Reflection;
using System.Collections.Generic;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using PeerChatDesktop;
class GroupCallsDiagnosticsTest {
    static string g=new string('a',32),epoch=new string('e',32),vr=new string('b',32),sr=new string('c',32),local=new string('1',64),p2=new string('2',64),p3=new string('3',64),part=new string('d',32);
    static void Check(bool v,[System.Runtime.CompilerServices.CallerLineNumber]int line=0){if(!v)throw new Exception("Group diagnostics regression at "+line);}
    static Dictionary<string,object> Device(long a,string p,string name,string generation){return new Dictionary<string,object>{{"accountId",a},{"publicIdentity",p},{"username",name},{"mediaGeneration",generation}};}
    static GroupMediaState Authority(string remoteGeneration){var me=Device(1,local,"You",part);var a=Device(2,p2,"Viewer A",remoteGeneration);var b=Device(3,p3,"Viewer B",part);return GroupMediaState.Parse(new Dictionary<string,object>{{"groupId",g},{"epoch",epoch},{"revision",3L},{"rosterGeneration",1L},{"rooms",new object[]{new Dictionary<string,object>{{"roomId",vr},{"kind","voice"},{"name","Voice room"},{"creatorAccountId",1L},{"creatorDevice",local},{"sharer",null},{"members",new object[]{me,a,b}}},new Dictionary<string,object>{{"roomId",sr},{"kind","screen_share"},{"name","Screen room"},{"creatorAccountId",1L},{"creatorDevice",local},{"sharer",me},{"members",new object[]{a,b}}}}}});}
    static string Route(string peer,long account,bool connected,string details="",bool video=false){var row=new Dictionary<string,object>{{"sourceKey",account+":"+peer+":"+part},{"connected",connected},{"turn",true},{"state",connected?"Connected":"Connecting"},{"sendPayloadBits",1000000},{"receivePayloadBits",2000000},{"received",10},{"decoded",5},{"presented",4},{"receivedPacketsPerSecond",500},{"decodedFps",27},{"presentedFps",26},{"details",details}};return new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(row);}
    public static GroupCallsInput Fixture(){var input=new GroupCallsInput{Title="SAMPLE FIXTURE — NOT PHYSICAL ACCEPTANCE",Device=local,Account=1,Profile=1,Discovery=1,Control="SAMPLE fixture authenticated control TLS",Authority=Authority(part),Roster=new ServerGroupRoster{GroupId=g,RosterGeneration=1,Members=new List<ServerGroupMember>{new ServerGroupMember{AccountId=1,State="member"},new ServerGroupMember{AccountId=2,State="member"},new ServerGroupMember{AccountId=3,State="member"}}}};string voice="{\"active\":true,\"captureBlocks\":200,\"encodedPackets\":200,\"mixedBlocks\":199,\"underrunBlocks\":0,\"aec_enabled\":true,\"aec_delay_ms\":20,\"routes\":["+Route(p2,2,true)+","+Route(p3,3,false)+"]}";string screen="{\"active\":true,\"encoderCount\":1,\"capturedFps\":30,\"encodedFps\":29,\"width\":1920,\"height\":1080,\"encoderQueueDrops\":0,\"routes\":["+Route(p2,2,true)+","+Route(p3,3,false)+"]}";input.Observations=new[]{new GroupMediaObservation(g,vr,epoch,1,local,part,"","voice",1,1,1,false,voice),new GroupMediaObservation(g,sr,epoch,1,local,part,part,"screen_share",2,1,1,true,screen)};return input;}
    static BindingFlags f=BindingFlags.Instance|BindingFlags.NonPublic;
    static object Get(object o,string name){return o.GetType().GetField(name,f).GetValue(o);}static void Set(object o,string name,object value){o.GetType().GetField(name,f).SetValue(o,value);}static object Call(object o,string name,params object[] args){return o.GetType().GetMethod(name,f).Invoke(o,args);}
    static IEnumerable<T> Children<T>(DependencyObject o) where T:DependencyObject{for(int n=0;n<VisualTreeHelper.GetChildrenCount(o);n++){var c=VisualTreeHelper.GetChild(o,n);if(c is T)yield return (T)c;foreach(var sub in Children<T>(c))yield return sub;}}
    static void Capture(Window w,string path){w.UpdateLayout();var surface=(FrameworkElement)w.Content;var bitmap=new RenderTargetBitmap((int)Math.Ceiling(surface.ActualWidth),(int)Math.Ceiling(surface.ActualHeight),96,96,PixelFormats.Pbgra32);var drawing=new DrawingVisual();using(var dc=drawing.RenderOpen())dc.DrawRectangle(new VisualBrush(surface),null,new Rect(0,0,surface.ActualWidth,surface.ActualHeight));bitmap.Render(drawing);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bitmap));using(var stream=System.IO.File.Create(path))png.Save(stream);}
    public static async Task Run(DesktopApplication desktop,string path){
        var input=Fixture();var p=GroupCallsProjection.Create(input);Check(p.Telemetry.VoiceActive&&p.Telemetry.ScreenActive&&p.Participants.Length==4);Check(p.Participants.Count(x=>x.Connected)==2);Check(p.Telemetry.UploadMbps==4);Check(p.Voice.Contains("Local capture/mix/AEC only")&&p.Voice.Contains("NetEq/concealment/processing costs: N/A"));Check(p.Participants.All(x=>!x.ReceivedFps.HasValue));
        var original=p.Context;input.Observations=new[]{new GroupMediaObservation(g,vr,epoch,1,local,part,"","voice",7,1,1,false,input.Observations[0].Raw)};Check(GroupCallsProjection.Create(input).Context!=original);
        input.Profile=2;Check(!GroupCallsProjection.Create(input).Telemetry.VoiceActive);input=Fixture();input.Discovery=2;Check(!GroupCallsProjection.Create(input).Telemetry.ScreenActive);
        input=Fixture();input.Authority=Authority(new string('f',32));p=GroupCallsProjection.Create(input);Check(p.Telemetry.UploadMbps==2&&p.Participants.Count(x=>x.Connected)==0);Check(p.Participants.Where(x=>x.Label.Contains("Viewer A")).All(x=>!x.SendMbps.HasValue));
        input=Fixture();input.Roster.Members.RemoveAt(2);Check(GroupCallsProjection.Create(input).Participants.Length==2);input.Roster.Members.Clear();Check(!GroupCallsProjection.Create(input).Telemetry.VoiceActive);
        input=Fixture();input.Room=sr;p=GroupCallsProjection.Create(input);Check(!p.Telemetry.VoiceActive&&p.Participants.Length==2&&p.Telemetry.UploadMbps==2);
        input=Fixture();input.Account=2;input.Device=p2;input.Observations=new[]{new GroupMediaObservation(g,sr,epoch,2,p2,part,part,"screen_share",9,1,1,false,"{\"active\":true,\"encoderCount\":0,\"routes\":["+Route(local,1,true,"security=DTLS-SRTP\nselected_ice_pair=TURN\nreceived_fps_access_units=28\ndecoder_queue_depth=2\ndecoder_oldest_queue_age_ms=40\nawaiting_recovery_idr=false")+"]}")};p=GroupCallsProjection.Create(input);var viewer=p.Participants.Single(x=>x.Kind=="screen_share"&&x.Label.Contains("Sharer"));Check(viewer.ReceivedFps==28&&viewer.DecodedFps==27&&viewer.PresentedFps==26);Check(viewer.State.Contains("presented")&&!viewer.Details.Contains("500 FPS"));
        input.Observations=new[]{new GroupMediaObservation(g,sr,epoch,2,p2,part,part,"screen_share",10,1,1,false,input.Observations[0].Raw.Replace("awaiting_recovery_idr=false","awaiting_recovery_idr=true"))};Check(GroupCallsProjection.Create(input).Participants.Single(x=>x.Kind=="screen_share"&&x.Label.Contains("Sharer")).State.Contains("Recovering"));
        Check(!GroupCallsProjection.Create(null).Telemetry.ScreenActive);input=Fixture();input.Observations=new[]{new GroupMediaObservation(g,vr,new string('f',32),1,local,part,"","voice",1,1,1,false,input.Observations[0].Raw)};Check(!GroupCallsProjection.Create(input).Telemetry.VoiceActive);
        input=Fixture();input.Observations=new[]{new GroupMediaObservation(g,vr,epoch,1,local,part,"","voice",1,1,1,false,input.Observations[0].Raw.Replace("Connected","password=private-fixture"))};Check(!GroupCallsProjection.Create(input).Network.Contains("private-fixture"));
        var watch=System.Diagnostics.Stopwatch.StartNew();for(int n=0;n<200;n++)GroupCallsProjection.Create(Fixture());watch.Stop();Console.WriteLine("Group fixture projection 200 reads ms="+watch.Elapsed.TotalMilliseconds.ToString("F2"));
        input=Fixture();Set(desktop,"groupDiagnosticTestInput",new Func<GroupCallsInput>(()=>input));Call(desktop,"OpenContextDiagnostics",DiagnosticSection.GroupCalls,g);Set(desktop,"nextGroupTelemetry",DateTime.MinValue);Call(desktop,"RefreshGroupTelemetry");
        var w=(Window)Get(desktop,"groupDiagnosticWindow");w.ShowInTaskbar=false;w.ShowActivated=false;w.Left=-20000;w.Width=1080;w.Height=780;var tabs=(TabControl)Get(desktop,"groupDiagnosticTabs");Check(tabs.Items.Count==7);
        var banner=(TextBlock)Get(desktop,"diagnosticBanner");banner.Text="SAMPLE FIXTURE — NOT PHYSICAL ACCEPTANCE";
        foreach(var pair in new[]{new[]{"0","Overview"},new[]{"1","ScreenShare"},new[]{"2","Voice"},new[]{"3","Participants"},new[]{"4","Network"}}){tabs.SelectedIndex=Int32.Parse(pair[0]);w.UpdateLayout();if(pair[1]=="Participants"){var exp=Children<Expander>(w).First();exp.IsExpanded=true;w.UpdateLayout();}if(pair[1]=="Network"){var exp=Children<Expander>(w).First();exp.IsExpanded=true;w.UpdateLayout();}Capture(w,System.IO.Path.Combine(path,"Group-"+pair[1]+".png"));}
        Check(Call(desktop,"GroupDiagnosticExport").ToString().Contains(g));Check(!Call(desktop,"GroupDiagnosticExport").ToString().Contains("private-fixture"));
        tabs.SelectedIndex=3;w.UpdateLayout();var entry=Children<Expander>(w).First();entry.IsExpanded=true;string selected=Get(desktop,"selectedGroupParticipant").ToString();Set(desktop,"nextGroupTelemetry",DateTime.MinValue);Call(desktop,"RefreshGroupTelemetry");Check(Get(desktop,"selectedGroupParticipant").ToString()==selected);
        input.Authority=Authority(new string('f',32));Set(desktop,"nextGroupTelemetry",DateTime.MinValue);Call(desktop,"RefreshGroupTelemetry");Check(!((GroupCallsProjection)Get(desktop,"groupCallDetails")).Participants.Any(x=>x.Key==selected));
        for(int n=0;n<140;n++){Set(desktop,"nextGroupTelemetry",DateTime.MinValue);Call(desktop,"RefreshGroupTelemetry");}Check(((System.Collections.ICollection)Get(desktop,"groupSamples")).Count<=120);Check(((System.Collections.ICollection)Get(desktop,"groupTelemetryEvents")).Count<=64);
        Set(desktop,"graphsPaused",true);int count=((System.Collections.ICollection)Get(desktop,"groupSamples")).Count;Set(desktop,"nextGroupTelemetry",DateTime.MinValue);Call(desktop,"RefreshGroupTelemetry");Check(((System.Collections.ICollection)Get(desktop,"groupSamples")).Count==count);Set(desktop,"graphsPaused",false);
        foreach(double width in new[]{540.0,800,1080}){w.Width=width;w.Height=420;w.UpdateLayout();Check(tabs.ActualWidth>0);foreach(TabItem tab in tabs.Items){tabs.SelectedItem=tab;w.UpdateLayout();Check(tab.Content!=null);}}
        foreach(double scale in new[]{1.0,1.25,1.5,2.0}){w.Width=640;w.Height=480;((FrameworkElement)w.Content).LayoutTransform=new ScaleTransform(scale,scale);w.UpdateLayout();Check(tabs.ActualWidth>0);}((FrameworkElement)w.Content).LayoutTransform=Transform.Identity;
        w.Close();Set(desktop,"groupDiagnosticTestInput",null);await Task.Delay(30);Check(Get(desktop,"groupDiagnosticWindow")==null);Console.WriteLine("PASS Group diagnostics: authenticated snapshots, participant ownership, simultaneous voice/screen, two viewers, stale sessions, room/profile changes, privacy, bounded graphs, navigation and resize.");
    }
